57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        String address = normalizeAddress(owner.getAddress());
111	        if (address.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        owner.setAddress(address);
115	        String telephone = toE164(owner.getTelephone());
116	        if (telephone == null) {
117	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
118	        }
119	        if (owner.getEmail() != null) {
120	            String email = normalizeEmail(owner.getEmail());
121	            if (email == null) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        for (Owner existing : this.clinicService.findAllOwners()) {
127	            if (telephone.equals(toE164(existing.getTelephone()))) {
128	                return new ResponseEntity<>(HttpStatus.CONFLICT);
129	            }
130	        }
131	        String lastNameKey = householdKey(owner.getLastName());
132	        String addressKey = householdKey(owner.getAddress());
133	        List<Owner> householdMembers = new ArrayList<>();
134	        for (Owner existing : this.clinicService.findAllOwners()) {
135	            if (lastNameKey.equals(householdKey(existing.getLastName()))
136	                && addressKey.equals(householdKey(existing.getAddress()))) {
137	                householdMembers.add(existing);
138	            }
139	        }
140	        if (!householdMembers.isEmpty()) {
141	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
142	                return new ResponseEntity<>(HttpStatus.CONFLICT);
143	            }
144	            String householdId = householdId(lastNameKey, addressKey);
145	            owner.setHouseholdId(householdId);
146	            for (Owner member : householdMembers) {
147	                if (!householdId.equals(member.getHouseholdId())) {
148	                    member.setHouseholdId(householdId);
149	                    this.clinicService.saveOwner(member);
150	                }
151	            }
152	        }
153	        owner.setTelephone(telephone);
154	        if (owner.getRegistrationDate() == null) {
155	            owner.setRegistrationDate(LocalDate.now());
156	        }
157	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
158	        this.clinicService.saveOwner(owner);
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
177	        this.clinicService.saveOwner(currentOwner);
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Transactional
183	    @Override
184	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        this.clinicService.deleteOwner(owner);
190	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        HttpHeaders headers = new HttpHeaders();
201	        Pet pet = petMapper.toPet(petFieldsDto);
202	        owner.setId(ownerId);
203	        pet.setOwner(owner);
204	        pet.getType().setName(null);
205	        this.clinicService.savePet(pet);
206	        PetDto petDto = petMapper.toPetDto(pet);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
208	            .buildAndExpand(pet.getId()).toUri());
209	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
215	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
216	        if (currentOwner != null) {
217	            Pet currentPet = this.clinicService.findPetById(petId);
218	            if (currentPet != null) {
219	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
220	                currentPet.setName(petFieldsDto.getName());
221	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
222	                this.clinicService.savePet(currentPet);
223	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
