229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
232	        HttpHeaders headers = new HttpHeaders();
233	        Visit visit = visitMapper.toVisit(visitFieldsDto);
234	        Pet pet = new Pet();
235	        pet.setId(petId);
236	        visit.setPet(pet);
237	        this.clinicService.saveVisit(visit);
238	        VisitDto visitDto = visitMapper.toVisitDto(visit);
239	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
240	            .buildAndExpand(visit.getId()).toUri());
241	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
242	    }
243	
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner != null) {
250	            Pet pet = owner.getPet(petId);
251	            if (pet != null) {
252	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    /**
259	     * Builds the customer code for a newly created owner, formatted
260	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
261	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
262	     * sequence equal to one more than the current number of owners.
263	     *
264	     * @param lastName the owner's last name
265	     * @return the assigned customer code (e.g. {@code 'SMI-0007'})
266	     */
267	    private String nextCustomerCode(String lastName) {
268	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
269	        int sequence = this.clinicService.findAllOwners().size() + 1;
270	        return String.format("%s-%04d", last3, sequence);
271	    }
272	
273	    /**
274	     * Canonical expansions applied to common street-type abbreviations during address
275	     * normalization. Keys and values are upper-cased so the lookup runs after the address
276	     * has itself been upper-cased.
277	     */
278	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
279	        "ST", "STREET",
280	        "RD", "ROAD",
281	        "AVE", "AVENUE");
282	
283	    /**
284	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
285	     * every run of internal whitespace is collapsed to a single space, the result is
286	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
287	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
288	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
289	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
290	     * returned and compared for household duplicates; an address that is blank once
291	     * normalized fails the required-field check.
292	     *
293	     * @param address the raw address value supplied by the client
294	     * @return the normalized address (empty string when {@code address} is null or blank)
295	     */
296	    private static String normalizeAddress(String address) {
297	        if (address == null) {
298	            return "";
299	        }
300	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
301	        if (collapsed.isEmpty()) {
302	            return "";
303	        }
304	        StringBuilder normalized = new StringBuilder(collapsed.length());
305	        for (String token : collapsed.split(" ")) {
306	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
307	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
308	            if (normalized.length() > 0) {
309	                normalized.append(' ');
310	            }
311	            normalized.append(expanded != null ? expanded : token);
312	        }
313	        return normalized.toString();
314	    }
315	
316	    /**
317	     * Normalizes a last name or address for household-duplicate comparison: leading and
318	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
319	     * single space and the result is lower-cased. Two owners are considered to share a
320	     * household when both their last names and addresses produce the same key.
321	     *
322	     * @param value the raw last name or address value
323	     * @return the normalized comparison key (empty string when {@code value} is null)
324	     */
325	    private static String householdKey(String value) {
326	        if (value == null) {
327	            return "";
328	        }
329	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
330	    }
331	
332	    /**
333	     * Derives the stable shared household identifier for the given normalized last name
334	     * and address keys. The identifier is deterministic — the same household (same
335	     * {@link #householdKey normalized} last name and address) always maps to the same
336	     * value — so every owner who joins a household is assigned an identical id. It is the
337	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
338	     * '<lastNameKey>|<addressKey>'}.
339	     *
340	     * @param lastNameKey the normalized last name key
341	     * @param addressKey  the normalized address key
342	     * @return the shared household identifier
343	     */
344	    private static String householdId(String lastNameKey, String addressKey) {
345	        String source = lastNameKey + "|" + addressKey;
346	        try {
347	            byte[] digest = MessageDigest.getInstance("SHA-256")
348	                .digest(source.getBytes(StandardCharsets.UTF_8));
349	            StringBuilder hex = new StringBuilder(digest.length * 2);
350	            for (byte b : digest) {
351	                hex.append(String.format("%02x", b));
352	            }
353	            return hex.substring(0, 12).toUpperCase();
354	        } catch (NoSuchAlgorithmException e) {
355	            throw new IllegalStateException("SHA-256 not available", e);
356	        }
357	    }
358	
359	    /**
360	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
361	     * and brackets are stripped. When the number already carries a leading {@code '+'}
362	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
363	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
364	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
365	     *
366	     * @param telephone the raw telephone value supplied by the client
367	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
368	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
369	     */
370	    private static String toE164(String telephone) {
371	        if (telephone == null) {
372	            return null;
373	        }
374	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
375	        String digits;
376	        if (cleaned.startsWith("+")) {
377	            digits = cleaned.substring(1);
378	        } else {
379	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
380	            digits = "61" + national;
381	        }
382	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
383	    }
384	
385	    /**
386	     * Normalizes an owner email for creation. A present email must be a syntactically
387	     * valid address; the returned value is lower-cased.
388	     *
389	     * @param email the raw email value supplied by the client (never {@code null} here)
390	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
391	     *         address (signalling a 400 Bad Request)
392	     */
393	    private static String normalizeEmail(String email) {
394	        String trimmed = email.trim();
395	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
396	            return null;
397	        }
398	        return trimmed.toLowerCase();
399	    }
400	}
